```kotlin
package com.student.todo

import android.content.BroadcastReceiver
import android.content.Context
import android.content.Intent
import kotlinx.coroutines.CoroutineScope
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.launch

class AlarmReceiver : BroadcastReceiver() {
    override fun onReceive(context: Context, intent: Intent) {
        val taskId = intent.getIntExtra("taskId", -1)
        val title = intent.getStringExtra("title") ?: "Task"

        if (taskId != -1) {
            NotificationHelper.showNotification(context, taskId, title)

            // Optional: Remove the reminder time from DB once it triggers
            val db = AppDatabase.getDatabase(context)
            CoroutineScope(Dispatchers.IO).launch {
                db.taskDao().getTaskById(taskId)?.let { task ->
                    db.taskDao().updateTask(task.copy(dueTime = null))
                }
            }
        }
    }
}
```

**3. `AlarmScheduler.kt`**
```kotlin
package com.student.todo

import android.app.AlarmManager
import android.app.PendingIntent
import android.content.Context
import android.content.Intent
import android.os.Build

object AlarmScheduler {
    fun scheduleAlarm(context: Context, taskId: Int, title: String, timeInMillis: Long) {
        val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
        val intent = Intent(context, AlarmReceiver::class.java).apply {
            putExtra("taskId", taskId)
            putExtra("title", title)
        }

        val pendingIntent = PendingIntent.getBroadcast(
            context,
            taskId,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )

        // For Android 12+ (S+), we need to check permission for exact alarms
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.S) {
            if (alarmManager.canScheduleExactAlarms()) {
                alarmManager.setExactAndAllowWhileIdle(
                    AlarmManager.RTC_WAKEUP,
                    timeInMillis,
                    pendingIntent
                )
            }
        } else {
            alarmManager.setExactAndAllowWhileIdle(
                AlarmManager.RTC_WAKEUP,
                timeInMillis,
                pendingIntent
            )
        }
    }

    fun cancelAlarm(context: Context, taskId: Int) {
        val alarmManager = context.getSystemService(Context.ALARM_SERVICE) as AlarmManager
        val intent = Intent(context, AlarmReceiver::class.java)
        val pendingIntent = PendingIntent.getBroadcast(
            context,
            taskId,
            intent,
            PendingIntent.FLAG_UPDATE_CURRENT or PendingIntent.FLAG_IMMUTABLE
        )
        alarmManager.cancel(pendingIntent)
    }
}
```

### 🧠 Step 6: ViewModel (Business Logic)
**`TaskViewModel.kt`**
```kotlin
package com.student.todo

import android.app.Application
import androidx.lifecycle.AndroidViewModel
import androidx.lifecycle.viewModelScope
import kotlinx.coroutines.flow.SharingStarted
import kotlinx.coroutines.flow.StateFlow
import kotlinx.coroutines.flow.stateIn
import kotlinx.coroutines.launch

class TaskViewModel(application: Application) : AndroidViewModel(application) {
    private val dao = (application as TodoApp).database.taskDao()

    val tasks: StateFlow<List<Task>> = dao.getAllTasks()
        .stateIn(viewModelScope, SharingStarted.Lazy, emptyList())

    fun addTask(title: String, description: String, dueTime: Long?) {
        viewModelScope.launch {
            val newTask = Task(title = title, description = description, dueTime = dueTime)
            val id = dao.insertTask(newTask)
            if (dueTime != null) {
                AlarmScheduler.scheduleAlarm(getApplication(), id.toInt(), title, dueTime)
            }
        }
    }

    fun updateTask(task: Task) {
        viewModelScope.launch {
            dao.updateTask(task)
            if (task.dueTime != null) {
                AlarmScheduler.scheduleAlarm(getApplication(), task.id, task.title, task.dueTime)
            } else {
                AlarmScheduler.cancelAlarm(getApplication(), task.id)
            }
        }
    }

    fun toggleCompletion(task: Task) {
        updateTask(task.copy(isCompleted = !task.isCompleted))
    }

    fun deleteTask(task: Task) {
        viewModelScope.launch {
            AlarmScheduler.cancelAlarm(getApplication(), task.id)
            dao.deleteTask(task)
        }
    }
}
```

