    if (arr == null || arr.length < 2) {
        throw new IllegalArgumentException("Array must contain at least two distinct elements.");
    }

    long largest = Long.MIN_VALUE;
    long secondLargest = Long.MIN_VALUE;

    for (int num : arr) {
        if (num > largest) {
            secondLargest = largest;
            largest = num;
        } else if (num < largest && num > secondLargest) {
            secondLargest = num;
        }
    }

    if (secondLargest == Long.MIN_VALUE) {
        throw new IllegalArgumentException("No second largest element found (all elements may be equal).");
    }

    return (int) secondLargest;
}
